xt","marks":[{"type":"bold"}],"text":"directement"},{"type":"text","text":" la gestion des utilisatrices — "},{"type":"text","marks":[{"type":"bold"}],"text":"plus d''onglets"},{"type":"text","text":" (« Chambres » et « Invités » supprimés). "},{"type":"text","marks":[{"type":"bold"}],"text":"Une seule liste"},{"type":"text","text":" rassemble les personnes "},{"type":"text","marks":[{"type":"bold"}],"text":"et"},{"type":"text","text":" leurs chambres. Principe : "},{"type":"text","marks":[{"type":"bold"}],"text":"une chambre = une place = un compte"},{"type":"text","text":". Les résidentes "},{"type":"text","marks":[{"type":"bold"}],"text":"ne s''inscrivent plus elles-mêmes"},{"type":"text","text":" — elles sont "},{"type":"text","marks":[{"type":"bold"}],"text":"invitées"},{"type":"text","text":" par l''intendance."}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"La liste des utilisatrices"},{"type":"text","text":" est classée par "},{"type":"text","marks":[{"type":"bold"}],"text":"résidence → étage → chambre"},{"type":"text","text":". Chaque ligne montre la "},{"type":"text","marks":[{"type":"bold"}],"text":"place"},{"type":"text","text":", son "},{"type":"text","marks":[{"type":"bold"}],"text":"occupante"},{"type":"text","text":" (ou "},{"type":"text","marks":[{"type":"bold"}],"text":"Libre"},{"type":"text","text":" / "},{"type":"text","marks":[{"type":"bold"}],"text":"Invitation envoyée"},{"type":"text","text":") et, pour une occupante, le "},{"type":"text","marks":[{"type":"bold"}],"text":"résumé de ses droits"},{"type":"text","text":". Selon l''état de la place :"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Libre"},{"type":"text","text":" → bouton "},{"type":"text","marks":[{"type":"bold"}],"text":"« Inviter »"},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":