":[{"type":"text","text":"Clique "},{"type":"text","marks":[{"type":"bold"}],"text":"« Inviter »"},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Deux possibilités :"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Nouvelle personne"},{"type":"text","text":" : saisis son "},{"type":"text","marks":[{"type":"bold"}],"text":"email"},{"type":"text","text":" → elle reçoit un email d''activation."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Compte désactivé"},{"type":"text","text":" (déjà eu un compte) : choisis-le dans la liste "},{"type":"text","marks":[{"type":"bold"}],"text":"« Réassigner une ancienne résidente »"},{"type":"text","text":" → son compte est "},{"type":"text","marks":[{"type":"bold"}],"text":"réactivé et réassigné sans nouvel email"},{"type":"text","text":". "},{"type":"text","marks":[{"type":"bold"}],"text":"Si cette personne avait des droits admin"},{"type":"text","text":", un choix apparaît : "},{"type":"text","marks":[{"type":"bold"}],"text":"repartir de zéro"},{"type":"text","text":" (simple résidente, recommandé) ou "},{"type":"text","marks":[{"type":"bold"}],"text":"garder ses anciens droits"},{"type":"text","text":"."}]}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Elle définit son mot de passe et complète son profil (résidence/chambre "},{"type":"text","marks":[{"type":"bold"}],"text":"imposées"},{"type":"text","text":") ; la place passe à "},{"type":"text","marks":[{"type":"bold"}],"text":"« Occupée »"},{"type":"text","text":"."}]}]}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Départ d''une résidente"},{"type":"text","text":" : bouton "},{"type":"text","marks":[{"type":"bold"}],"text":"« Libérer / désactiver »"},{"type":"text","text":" (⤴) → le compte est "},{"type":"text","marks":[{"type":"bold"}],"text":"désactivé"},{"type":"text","text":" (il ne peut plus se connecter, mais son "},{"type":"text","marks":[{"type":"bold"}],"text":"historique de repas/présence est conservé"},{"type":"text","text":" pour la compta) et la "},{"type":"text","marks":[{"type":"bold"}],"text":"place se libère"},{"type":"text","text":" (réattribuable)."}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Comptes désactivés"},{"type":"text","text":" : un panneau repliable en bas liste les anciens comptes (avec leurs droits en sommeil). Ils se réactivent via "},{"type":"text","marks":[{"type":"bold"}],"text":"« Inviter »"},{"type":"text","text":" sur une chambre libre."}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Supprimer définitivement un compte"},{"type":"text","text":" : dans ce même panneau, le bouton 🗑 efface le compte pour de bon. Il n''est proposé que sur un compte "},{"type":"text","marks":[{"type":"bold"}],"text":"déjà désactivé"},{"type":"text","text":" — pour supprimer quelqu''un d''actif, il faut donc d''abord le "},{"type":"text","marks":[{"type":"bold"}],"text":"libérer / désactiver"},{"type":"text","text":". Un niveau "},{"type":"text","marks":[{"type":"bold"}],"text":"Édition"},{"type":"text","text":" sur Comptes suffit ; seul un super-admin peut supprimer un autre super-admin."}]},{"type":"blockquote","content":[{"type":"paragraph","content":[{"type":"text","text":"⚠️ "},{"type":"text","marks":[{"type":"bold"}],"text":"À ne faire qu''après avoir facturé la période."},{"type":"text","text":" La "},{"type":"text","marks":[{"type":"italic"}],"text":"désactivation"},{"type":"text","text":" conserve l''historique des repas ; la "},{"type":"text","marks":[{"type":"italic"}],"text":"suppression"},{"type":"text","text":", elle, retire la personne de la "},{"type":"text","marks":[{"type":"bold"}],"text":"comptabilité passée"},{"type":"text","text":". Une fois supprimée, on ne peut plus la retrouver ni la réactiver."}]}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Gérer les blocs, chambres & étages"},{"type":"text","text":" : un second panneau repliable, "},{"type":"text","marks":[{"type":"bold"}],"text":"réservé au super-admin"},{"type":"text","text":", contient la "},{"type":"text","marks":[{"type":"bold"}],"text":"structure physique"},{"type":"text","text":" du foyer, séparée de la liste des personnes."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Blocs du foyer"},{"type":"text","text":" (en haut du panneau) — un « bloc », c''est une "},{"type":"text","marks":[{"type":"bold"}],"text":"résidence"},{"type":"text","text":" (Résidence 12, Résidence 36) ou un "},{"type":"text","marks":[{"type":"bold"}],"text":"ensemble de postes"},{"type":"text","text":" (Corail, l''intendance). On peut en "},{"type":"text","marks":[{"type":"bold"}],"text":"ajouter"},{"type":"text","text":", les "},{"type":"text","marks":[{"type":"bold"}],"text":"renommer"},{"type":"text","text":", changer leur "},{"type":"text","marks":[{"type":"bold"}],"text":"couleur"},{"type":"text","text":", les "},{"type":"text","marks":[{"type":"bold"}],"text":"réordonner"},{"type":"text","text":" (↑ ↓), les "},{"type":"text","marks":[{"type":"bold"}],"text":"désactiver"},{"type":"text","text":" ou les "},{"type":"text","marks":[{"type":"bold"}],"text":"supprimer"},{"type":"text","text":". À la création, on choisit ce que le bloc contient : "},{"type":"text","marks":[{"type":"italic"}],"text":"des chambres réparties par étage"},{"type":"text","text":" (une résidence) ou "},{"type":"text","marks":[{"type":"italic"}],"text":"des postes sans étage"},{"type":"text","text":" (une intendance)."}]},{"type":"blockquote","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Un bloc ajouté ici obtient tout de suite son propre encadré partout"},{"type":"text","text":" : comptabilité des repas, organisation des services, présences au foyer, ciblage des événements, rattachement d''une option de repas et intercalaires de l''accueil. Rien d''autre n''est à faire. "},{"type":"text","marks":[{"type":"bold"}],"text":"Suppression"},{"type":"text","text":" : possible seulement si le bloc ne contient "},{"type":"text","marks":[{"type":"bold"}],"text":"aucune chambre/poste"},{"type":"text","text":" et "},{"type":"text","marks":[{"type":"bold"}],"text":"aucun compte"},{"type":"text","text":" (même parti). Sinon, le "},{"type":"text","marks":[{"type":"bold"}],"text":"désactiver"},{"type":"text","text":". Et son contenu (chambres ou postes) se "},{"type":"text","marks":[{"type":"bold"}],"text":"fige"},{"type":"text","text":" dès qu''il contient une place."}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Étages"},{"type":"text","text":", dans chaque bloc « résidence » : "},{"type":"text","marks":[{"type":"bold"}],"text":"ajouter / renommer / réordonner (↑ ↓) / supprimer"},{"type":"text","text":". Un étage peut exister "},{"type":"text","marks":[{"type":"bold"}],"text":"avant"},{"type":"text","text":" d''avoir la moindre chambre — c''est ainsi qu''on dessine la structure d''un foyer qui démarre. Il ne se supprime que "},{"type":"text","marks":[{"type":"bold"}],"text":"vide"},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Chambres"},{"type":"text","text":", à l''intérieur de chaque étage (bouton "},{"type":"text","marks":[{"type":"bold"}],"text":"« + Chambre »"},{"type":"text","text":" sur la ligne de l''étage), et "},{"type":"text","marks":[{"type":"bold"}],"text":"postes"},{"type":"text","text":" pour un bloc d''intendance : "},{"type":"text","marks":[{"type":"bold"}],"text":"ajouter / modifier / désactiver / supprimer"},{"type":"text","text":". L''ajout est rare une fois le foyer en place. Une chambre désactivée disparaît de la liste des utilisatrices."}]},{"type":"blockquote","content":[{"type":"paragraph","content":[{"type":"text","text":"Le formulaire de chambre "},{"type":"text","marks":[{"type":"bold"}],"text":"choisit son étage dans la liste"},{"type":"text","text":" : on ne le tape plus à la main, ce qui évitait qu''« Étage 3 » et « étage 3 » deviennent deux étages différents. Renommer un étage est sans risque : ses chambres et les événements ciblés dessus suivent."}]}]}]}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Supprimer"},{"type":"text","text":" un compte reste possible mais "},{"type":"text","marks":[{"type":"bold"}],"text":"irréversible"},{"type":"text","text":" (réservé au super-admin) : pour un simple départ, préférer la "},{"type":"text","marks":[{"type":"bold"}],"text":"désactivation"},{"type":"text","text":" ci-dessus."}]},{"type":"blockquote","content":[{"type":"paragraph","content":[{"type":"text","text":"Le compte "},{"type":"text","marks":[{"type":"bold"}],"text":"super-admin"},{"type":"text","text":" (technique) n''occupe aucune place et n''apparaît pas dans les listes. Un encart "},{"type":"text","marks":[{"type":"bold"}],"text":"« Sans chambre attribuée »"},{"type":"text","text":" (situation anormale) n''est visible que du "},{"type":"text","marks":[{"type":"bold"}],"text":"compte technique"},{"type":"text","text":" (maintenance) : il permet d''"},{"type":"text","marks":[{"type":"bold"}],"text":"attribuer une chambre"},{"type":"text","text":", régler les "},{"type":"text","marks":[{"type":"bold"}],"text":"droits"},{"type":"text","text":" ou "},{"type":"text","marks":[{"type":"bold"}],"text":"supprimer"},{"type":"text","text":" le compte concerné."}]}]},{"type":"blockquote","content":[{"type":"paragraph","content":[{"type":"text","text":"Les "},{"type":"text","marks":[{"type":"bold"}],"text":"invitées"},{"type":"text","text":" (comptes simplifiés pour les repas) conservent l''"},{"type":"text","marks":[{"type":"bold"}],"text":"inscription libre"},{"type":"text","text":" (« Inscription invitée » sur l''écran de connexion) et n''occupent pas de place. Elles ne sont plus gérées depuis un onglet dédié ; on les invite directement à un repas depuis "},{"type":"text","marks":[{"type":"bold"}],"text":"Repas de la semaine"},{"type":"text","text":". N''occupant pas de place, elles "},{"type":"text","marks":[{"type":"bold"}],"text":"n''apparaissent pas"},{"type":"text","text":" dans les écrans d''intendance (voir ci-dessous)."}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"3.1. Qui apparaît dans les autres écrans ?"}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Cet écran est la source de tout le reste de l''appli."},{"type":"text","text":" Une personne apparaît dans les repas, la comptabilité, l''organisation, les détails, les présences au foyer, le détail des absences, le ciblage des événements et les listes de personnes "},{"type":"text","marks":[{"type":"bold"}],"text":"si et seulement si son compte est activé ici"},{"type":"text","text":", c''est-à-dire "},{"type":"text","marks":[{"type":"bold"}],"text":"actif et rattaché à une chambre ou à un poste"},{"type":"text","text":"."}]},{"type":"paragraph","content":[{"type":"text","text":"N''apparaissent donc "},{"type":"text","marks":[{"type":"bold"}],"text":"pas"},{"type":"text","text":" : les "},{"type":"text","marks":[{"type":"bold"}],"text":"comptes désactivés"},{"type":"text","text":" (départs), les comptes "},{"type":"text","marks":[{"type":"bold"}],"text":"actifs sans chambre ni poste"},{"type":"text","text":", le compte "},{"type":"text","marks":[{"type":"bold"}],"text":"technique"},{"type":"text","text":", et les "},{"type":"text","marks":[{"type":"bold"}],"text":"invitées"},{"type":"text","text":"."}]},{"type":"paragraph","content":[{"type":"text","text":"Deux précisions utiles :"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"L''historique n''est jamais perdu."},{"type":"text","text":" Une personne partie en cours de mois reste affichée là où elle a une donnée enregistrée sur la période consultée : ses "},{"type":"text","marks":[{"type":"bold"}],"text":"repas restent comptés"},{"type":"text","text":" (donc facturables) et ses "},{"type":"text","marks":[{"type":"bold"}],"text":"absences déclarées"},{"type":"text","text":" restent visibles — mais seulement les jours concernés, jamais comme « au foyer »."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"On ne peut plus l''inscrire."},{"type":"text","text":" Quand tu ajoutes quelqu''un à une option de repas ou que tu enregistres une nouvelle absence, seuls les "},{"type":"text","marks":[{"type":"bold"}],"text":"comptes activés"},{"type":"text","text":" te sont proposés."}]}]}]},{"type":"blockquote","content":[{"type":"paragraph","content":[{"type":"text","text":"⚠️ "},{"type":"text","marks":[{"type":"bold"}],"text":"Si quelqu''un a disparu d''un écran"},{"type":"text","text":", la cause est presque toujours ici : son compte est "},{"type":"text","marks":[{"type":"bold"}],"text":"désactivé"},{"type":"text","text":", ou "},{"type":"text","marks":[{"type":"bold"}],"text":"actif sans chambre ni poste"},{"type":"text","text":". Attribue-lui une place (bouton "},{"type":"text","marks":[{"type":"bold"}],"text":"« Inviter »"},{"type":"text","text":" sur une place libre, ou "},{"type":"text","marks":[{"type":"bold"}],"text":"« Déplacer »"},{"type":"text","text":") et elle réapparaît partout."}]}]},{"type":"horizontalRule"},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"3.2. Groupes de personnes"}]},{"type":"paragraph","content":[{"type":"text","text":"Un "},{"type":"text","marks":[{"type":"bold"}],"text":"groupe"},{"type":"text","text":" rassemble des personnes sous un nom libre — « Staff 12 », « Intendance », « Responsables événements ». Il sert à "},{"type":"text","marks":[{"type":"bold"}],"text":"cibler la visibilité"},{"type":"text","text":" d''un contenu : un événement, une option de repas ou une rubrique de l''onglet Administratif peuvent être réservés aux membres d''un groupe."}]},{"type":"blockquote","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Un groupe ne donne aucun droit."},{"type":"text","text":" Mettre quelqu''un dans « Intendance » ne lui ouvre aucun écran d''administration : cela lui rend seulement visibles les contenus ciblés sur ce groupe. Les droits se règlent toujours avec le bouton "},{"type":"text","marks":[{"type":"bold"}],"text":"« Droits »"},{"type":"text","text":", section par section."}]}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Créer et composer un groupe"},{"type":"text","text":" (Comptes — Édition) : panneau repliable "},{"type":"text","marks":[{"type":"bold"}],"text":"Groupes"},{"type":"text","text":" en bas de l''écran Administration."}]},{"type":"orderedList","attrs":{"start":1,"type":null},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"« Nouveau groupe »"},{"type":"text","text":" → saisis un nom → ✓."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Clique le nom du groupe pour le déplier : coche les personnes qui en font partie. L''enregistrement est immédiat. Un "},{"type":"text","marks":[{"type":"bold"}],"text":"champ de recherche"},{"type":"text","text":" permet de retrouver quelqu''un par son nom, son prénom ou sa chambre sans faire défiler toute la liste — les personnes "},{"type":"text","marks":[{"type":"bold"}],"text":"déjà dans le groupe"},{"type":"text","text":" restent affichées quoi que tu tapes, pour que tu puisses toujours les décocher."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Les crayons ✏️ et 🗑 renomment et suppriment le groupe."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Une personne peut appartenir à "},{"type":"text","marks":[{"type":"bold"}],"text":"plusieurs groupes"},{"type":"text","text":". Ses groupes s''affichent en "},{"type":"text","marks":[{"type":"bold"}],"text":"pastilles, juste à côté de son nom"},{"type":"text","text":" dans la liste des utilisatrices — pratique pour vérifier d''un coup d''œil qui est où. Chaque groupe a sa "},{"type":"text","marks":[{"type":"bold"}],"text":"propre couleur"},{"type":"text","text":", attribuée automatiquement et "},{"type":"text","marks":[{"type":"bold"}],"text":"stable"},{"type":"text","text":" : elle ne change pas si tu renommes le groupe, et c''est la même partout (liste, panneau Groupes, profil de l''habitante)."}]},{"type":"blockquote","content":[{"type":"paragraph","content":[{"type":"text","text":"⚠️ "},{"type":"text","marks":[{"type":"bold"}],"text":"Un groupe ne se met pas à jour tout seul."},{"type":"text","text":" Contrairement au ciblage « Résidence 12 » ou « Étage 3 », qui inclut automatiquement toute nouvelle arrivante, un groupe ne contient que les personnes que tu y as mises. Quand une nouvelle intendante arrive, pense à l''ajouter — sinon elle ne verra pas les contenus réservés."}]}]},{"type":"blockquote","content":[{"type":"paragraph","content":[{"type":"text","text":"Un groupe "},{"type":"text","marks":[{"type":"bold"}],"text":"encore utilisé"},{"type":"text","text":" pour cibler un contenu ne peut pas être supprimé : l''appli te dit lequel. Retire-le d''abord de ce contenu."}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"3.3. Qui voit quoi : le ciblage"}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Événements"},{"type":"text","text":", "},{"type":"text","marks":[{"type":"bold"}],"text":"options de repas"},{"type":"text","text":" et "},{"type":"text","marks":[{"type":"bold"}],"text":"rubriques Administratif"},{"type":"text","text":" utilisent tous le "},{"type":"text","marks":[{"type":"bold"}],"text":"même sélecteur"},{"type":"text","text":" :"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"coche des "},{"type":"text","marks":[{"type":"bold"}],"text":"résidences"},{"type":"text","text":" entières et/ou des "},{"type":"text","marks":[{"type":"bold"}],"text":"étages"},{"type":"text","text":" précis ;"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"coche des "},{"type":"text","marks":[{"type":"bold"}],"text":"groupes"},{"type":"text","text":" ;"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"la liste des "},{"type":"text","marks":[{"type":"bold"}],"text":"personnes concernées"},{"type":"text","text":" s''affiche dessous : décoche quelqu''un pour l''"},{"type":"text","marks":[{"type":"bold"}],"text":"exclure nommément"},{"type":"text","text":"."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Les critères s''"},{"type":"text","marks":[{"type":"bold"}],"text":"additionnent"},{"type":"text","text":" : une personne visée par la résidence "},{"type":"text","marks":[{"type":"bold"}],"text":"ou"},{"type":"text","text":" par le groupe est concernée. "},{"type":"text","marks":[{"type":"bold"}],"text":"Ne rien cocher = visible par toutes."}]},{"type":"paragraph","content":[{"type":"text","text":"Ce ciblage est appliqué "},{"type":"text","marks":[{"type":"bold"}],"text":"côté serveur"},{"type":"text","text":" : une rubrique qui ne concerne pas une habitante ne lui est même pas envoyée, et l''appli refuse une inscription à une option de repas qui ne lui est pas proposée."}]},{"type":"blockquote","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Les cases « réservé aux administratrices » et « réservé au staff » n''existent plus."},{"type":"text","text":" Elles visaient "},{"type":"text","marks":[{"type":"italic"}],"text":"toute"},{"type":"text","text":" personne ayant un droit d''intendance, fût-ce sur une seule section sans rapport. Pour réserver un contenu à l''intendance, "},{"type":"text","marks":[{"type":"bold"}],"text":"crée un groupe"},{"type":"text","text":" (ex. « Intendance ») et cible-le dessus : tu choisis exactement qui le voit."}]},{"type":"paragraph","content":[{"type":"text","text":"⚠️ "},{"type":"text","marks":[{"type":"bold"}],"text":"Un contenu sans aucun ciblage est visible par toutes."},{"type":"text","text":" C''est le comportement voulu pour la plupart des rubriques et des options ; ne l''oublie pas pour celles qui doivent rester internes."}]}]},{"type":"horizontalRule"},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"4. Réglages (heures de verrouillage)"}]},{"type":"paragraph","content":[{"type":"text","text":"Il n''y a plus d''onglet "},{"type":"text","marks":[{"type":"bold"}],"text":"Paramètres"},{"type":"text","text":" séparé : les réglages sont désormais "},{"type":"text","marks":[{"type":"bold"}],"text":"au plus près de leur usage"},{"type":"text","text":"."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Verrouillage des repas"},{"type":"text","text":" (heure limite du jour + option week-end) → dans "},{"type":"text","marks":[{"type":"bold"}],"text":"Paramétrer les repas"},{"type":"text","text":" (§5)."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Verrouillage des présences"},{"type":"text","text":" (heure limite pour modifier sa présence au foyer) → en haut de la "},{"type":"text","marks":[{"type":"bold"}],"text":"vue Présences"},{"type":"text","text":" (§6)."}]}]}]},{"type":"horizontalRule"},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"5. Paramétrer les repas"}]},{"type":"paragraph","content":[{"type":"text","text":"Accès : depuis la "},{"type":"text","marks":[{"type":"bold"}],"text":"barre de navigation repas"},{"type":"text","text":" (pastilles présentes sur tous les écrans repas) → "},{"type":"text","marks":[{"type":"bold"}],"text":"Paramétrer les repas"},{"type":"text","text":". L''écran comporte deux parties."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"5.1. Catalogue d''options"}]},{"type":"paragraph","content":[{"type":"text","text":"La liste des "},{"type":"text","marks":[{"type":"bold"}],"text":"options"},{"type":"text","text":" que le foyer peut proposer (ex. « Repas classique », « Apéro dînatoire », « Pique-nique »). Pour chaque option :"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Libellé"},{"type":"text","text":" (ce que voit la résidente) ;"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Lieu"},{"type":"text","text":" : "},{"type":"text","marks":[{"type":"bold"}],"text":"12"},{"type":"text","text":", "},{"type":"text","marks":[{"type":"bold"}],"text":"36"},{"type":"text","text":", ou "},{"type":"text","marks":[{"type":"bold"}],"text":"« Résidence de la personne »"},{"type":"text","text":" (le couvert est alors compté dans la résidence de l''inscrite) — c''est ce qui détermine dans quelle résidence le repas est "},{"type":"text","marks":[{"type":"bold"}],"text":"regroupé/facturé"},{"type":"text","text":" ;"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Délai (jours avant)"},{"type":"text","text":" : "},{"type":"text","marks":[{"type":"code"}],"text":"0"},{"type":"text","text":" = clôture "},{"type":"text","marks":[{"type":"bold"}],"text":"le jour même"},{"type":"text","text":" à l''heure de verrouillage ; "},{"type":"text","marks":[{"type":"code"}],"text":"+1"},{"type":"text","text":" par jour d''avance (ex. un pique-nique en "},{"type":"text","marks":[{"type":"code"}],"text":"1"},{"type":"text","text":" ferme "},{"type":"text","marks":[{"type":"bold"}],"text":"la veille"},{"type":"text","text":") ;"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Réservée à l''intendance"},{"type":"text","text":" : l''option n''apparaît qu''aux admins ;"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Active / inactive"},{"type":"text","text":" : une option inactive n''est jamais proposée (sans être supprimée)."}]}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"5.2. Ouverture des services"}]},{"type":"paragraph","content":[{"type":"text","text":"C''est ici qu''on décide, "},{"type":"text","marks":[{"type":"bold"}],"text":"jour par jour et par service"},{"type":"text","text":" (déjeuner / dîner), "},{"type":"text","marks":[{"type":"bold"}],"text":"quelles options sont proposées"},{"type":"text","text":" aux résidentes. Un service "},{"type":"text","marks":[{"type":"bold"}],"text":"sans aucune option ouverte"},{"type":"text","text":" s''affiche "},{"type":"text","marks":[{"type":"bold"}],"text":"« fermé »"},{"type":"text","text":" côté résidente."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Dupliquer sur une plage"},{"type":"text","text":" : reporter les options d''un jour sur plusieurs dates en une fois (sélecteur multi-dates), pour ouvrir toute une semaine rapidement."}]}]}]},{"type":"blockquote","content":[{"type":"paragraph","content":[{"type":"text","text":"⚠️ "},{"type":"text","marks":[{"type":"bold"}],"text":"À faire régulièrement"},{"type":"text","text":" : sans options créées "},{"type":"text","marks":[{"type":"bold"}],"text":"et"},{"type":"text","text":" de services ouverts, les résidentes voient « Service fermé » et ne peuvent pas s''inscrire."}]}]},{"type":"horizontalRule"},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"6. Présences au foyer (vue staff)"}]},{"type":"paragraph","content":[{"type":"text","text":"Via l''onglet 🧍 "},{"type":"text","marks":[{"type":"bold"}],"text":"Présence foyer"},{"type":"text","text":" → "},{"type":"text","marks":[{"type":"bold"}],"text":"« Voir les présences »"},{"type":"text","text":". Elle indique "},{"type":"text","marks":[{"type":"bold"}],"text":"qui est au foyer ou sorti"},{"type":"text","text":", "},{"type":"text","marks":[{"type":"bold"}],"text":"par résidence"},{"type":"text","text":", déduit des "},{"type":"text","marks":[{"type":"bold"}],"text":"séjours d''absence"},{"type":"text","text":"."}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Choisir la période"},{"type":"text","text":" : deux champs de date en haut (par défaut une semaine à partir d''aujourd''hui)."}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Lire les jours"},{"type":"text","text":" : les jours sont "},{"type":"text","marks":[{"type":"bold"}],"text":"empilés"},{"type":"text","text":". Pour chaque jour et chaque résidence, deux compteurs — "},{"type":"text","marks":[{"type":"bold"}],"text":"Au foyer"},{"type":"text","text":" (vert) et "},{"type":"text","marks":[{"type":"bold"}],"text":"Sorties"},{"type":"text","text":" (rouge). "},{"type":"text","marks":[{"type":"bold"}],"text":"Chaque nombre est cliquable"},{"type":"text","text":" : il ouvre la "},{"type":"text","marks":[{"type":"bold"}],"text":"liste des personnes"},{"type":"text","text":" derrière ce nombre."}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Vue d''ensemble"},{"type":"text","text":" : le bouton "},{"type":"text","marks":[{"type":"bold"}],"text":"« Voir le détail »"},{"type":"text","text":" ouvre un "},{"type":"text","marks":[{"type":"bold"}],"text":"tableau"},{"type":"text","text":" — en lignes les habitantes (classées "},{"type":"text","marks":[{"type":"bold"}],"text":"résidence → étage → chambre → nom"},{"type":"text","text":", invitées en fin de résidence), en colonnes les jours, chaque case indiquant "},{"type":"text","marks":[{"type":"bold"}],"text":"P"},{"type":"text","text":" (au foyer) ou "},{"type":"text","marks":[{"type":"bold"}],"text":"A"},{"type":"text","text":" (sortie). "},{"type":"text","marks":[{"type":"italic"}],"text":"Cette structure de tableau est réutilisée partout (présences, repas) pour ne pas se perdre."},{"type":"text","text":" Le bouton "},{"type":"text","marks":[{"type":"bold"}],"text":"« Exporter (CSV) »"},{"type":"text","text":" y télécharge le tableau (comme pour les repas)."}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Modifier une présence (Absences — Édition)"},{"type":"text","text":" : dans la liste ouverte au clic sur un compteur, chaque personne peut être basculée "},{"type":"text","marks":[{"type":"bold"}],"text":"Au foyer ↔ Sortie"},{"type":"text","text":" pour ce jour, et on peut "},{"type":"text","marks":[{"type":"bold"}],"text":"ajouter"},{"type":"text","text":" quelqu''un — sur le même principe que l''édition des inscriptions repas. Le réglage de l''"},{"type":"text","marks":[{"type":"bold"}],"text":"heure limite"},{"type":"text","text":" pour modifier une présence se trouve "},{"type":"text","marks":[{"type":"bold"}],"text":"en haut de cette vue"},{"type":"text","text":"."}]},{"type":"blockquote","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Qui figure dans cette vue ?"},{"type":"text","text":" Les "},{"type":"text","marks":[{"type":"bold"}],"text":"comptes activés"},{"type":"text","text":" de chaque résidence (voir §3.1). Une personne partie n''y apparaît "},{"type":"text","marks":[{"type":"bold"}],"text":"que"},{"type":"text","text":" les jours couverts par une absence qu''elle avait déclarée ; sa case est "},{"type":"text","marks":[{"type":"bold"}],"text":"vide (—)"},{"type":"text","text":" les autres jours, et elle n''est jamais comptée « au foyer »."}]}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Marquer une absence ou une présence"},{"type":"text","text":" : bouton "},{"type":"text","marks":[{"type":"bold"}],"text":"« Ajouter une absence »"},{"type":"text","text":"."}]},{"type":"orderedList","attrs":{"start":1,"type":null},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Choisis la "},{"type":"text","marks":[{"type":"bold"}],"text":"résidence"},{"type":"text","text":", puis la "},{"type":"text","marks":[{"type":"bold"}],"text":"personne"},{"type":"text","text":" — seuls les "},{"type":"text","marks":[{"type":"bold"}],"text":"comptes activés"},{"type":"text","text":" sont proposés (§3.1)."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Choisis "},{"type":"text","marks":[{"type":"bold"}],"text":"« Absente »"},{"type":"text","text":" (crée un séjour) ou "},{"type":"text","marks":[{"type":"bold"}],"text":"« Présente »"},{"type":"text","text":" (retire les absences déjà déclarées sur la période — pour corriger ou faire revenir quelqu''un)."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Renseigne la "},{"type":"text","marks":[{"type":"bold"}],"text":"période"},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Pour une absence, laisse cochée (ou décoche) la case "},{"type":"text","marks":[{"type":"bold"}],"text":"« Noter Non aux repas dans l''intervalle »"},{"type":"text","text":" — "},{"type":"text","marks":[{"type":"bold"}],"text":"cochée par défaut"},{"type":"text","text":", c''est la même que celle dont dispose l''habitante. Cochée, les repas des "},{"type":"text","marks":[{"type":"bold"}],"text":"jours intérieurs"},{"type":"text","text":" du séjour sont comptés "},{"type":"text","marks":[{"type":"bold"}],"text":"« Non »"},{"type":"text","text":" et la personne apparaît "},{"type":"text","marks":[{"type":"bold"}],"text":"🌙 absente"},{"type":"text","text":" dans les vues repas. Décochée, l''absence "},{"type":"text","marks":[{"type":"bold"}],"text":"n''a aucun effet"},{"type":"text","text":" sur les repas (utile pour quelqu''un qui dort ailleurs mais mange au foyer)."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Valide."}]}]}]},{"type":"blockquote","content":[{"type":"paragraph","content":[{"type":"text","text":"Cette case "},{"type":"text","marks":[{"type":"bold"}],"text":"ne modifie pas"},{"type":"text","text":" les inscriptions enregistrées : elle les "},{"type":"text","marks":[{"type":"bold"}],"text":"neutralise"},{"type":"text","text":" le temps du séjour. Si tu raccourcis ou supprimes l''absence, les choix d''origine réapparaissent tels quels."}]}]},{"type":"horizontalRule"},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"7. Inscriptions aux repas & comptabilité"}]},{"type":"paragraph","content":[{"type":"text","text":"Accès : "},{"type":"text","marks":[{"type":"bold"}],"text":"barre de navigation repas"},{"type":"text","text":" → "},{"type":"text","marks":[{"type":"bold"}],"text":"Inscriptions & compta"},{"type":"text","text":". Deux onglets, sur une "},{"type":"text","marks":[{"type":"bold"}],"text":"période choisie"},{"type":"text","text":" (sélecteur de dates en haut)."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"Onglet « Organisation » — repas à préparer"}]},{"type":"paragraph","content":[{"type":"text","text":"Les jours sont "},{"type":"text","marks":[{"type":"bold"}],"text":"empilés"},{"type":"text","text":" ; pour chaque jour et chaque résidence, les "},{"type":"text","marks":[{"type":"bold"}],"text":"options ouvertes"},{"type":"text","text":" au midi et au soir, avec leur nombre d''inscrits. "},{"type":"text","marks":[{"type":"bold"}],"text":"Chaque option est cliquable"},{"type":"text","text":" → la "},{"type":"text","marks":[{"type":"bold"}],"text":"liste des personnes comptées"},{"type":"text","text":". Les "},{"type":"text","marks":[{"type":"bold"}],"text":"invités"},{"type":"text","text":" ne forment plus une tuile à part : chacun est compté "},{"type":"text","marks":[{"type":"bold"}],"text":"dans l''option"},{"type":"text","text":" à laquelle il est rattaché et apparaît dans cette liste, annoté "},{"type":"text","marks":[{"type":"bold"}],"text":"« invité par Prénom Nom »"},{"type":"text","text":"."}]},{"type":"blockquote","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Édition (niveau ≥ 3)."},{"type":"text","text":" Dans cette liste, une admin "},{"type":"text","marks":[{"type":"bold"}],"text":"édition"},{"type":"text","text":" peut corriger les inscriptions, même après l''heure de verrouillage : "},{"type":"text","marks":[{"type":"bold"}],"text":"changer l''option"},{"type":"text","text":" de chaque inscrit (ou la passer à "},{"type":"text","marks":[{"type":"bold"}],"text":"« Non »"},{"type":"text","text":", ou "},{"type":"text","marks":[{"type":"bold"}],"text":"retirer sa réponse"},{"type":"text","text":"), "},{"type":"text","marks":[{"type":"bold"}],"text":"ajouter une résidente"},{"type":"text","text":" — seuls les "},{"type":"text","marks":[{"type":"bold"}],"text":"comptes activés"},{"type":"text","text":" sont proposés (§3.1) — (déplacée automatiquement si elle était inscrite ailleurs pour ce service), et "},{"type":"text","marks":[{"type":"bold"}],"text":"ajouter / retirer un invité"},{"type":"text","text":" — au choix "},{"type":"text","marks":[{"type":"bold"}],"text":"depuis le carnet"},{"type":"text","text":" (champ de recherche parmi les invités déjà venus) ou "},{"type":"text","marks":[{"type":"bold"}],"text":"nouveau"},{"type":"text","text":" ("},{"type":"text","marks":[{"type":"bold"}],"text":"le nom ou le prénom suffit"},{"type":"text","text":") — en indiquant la "},{"type":"text","marks":[{"type":"bold"}],"text":"résidente qui invite"},{"type":"text","text":" (pour la comptabilité). Tout se reporte aussitôt sur le "},{"type":"text","marks":[{"type":"bold"}],"text":"détail"},{"type":"text","text":" et la "},{"type":"text","marks":[{"type":"bold"}],"text":"compta"},{"type":"text","text":"."}]}]},{"type":"blockquote","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Un invité mange ce que son invitante peut choisir."},{"type":"text","text":" La liste « Invité par » ne propose que les résidentes à qui "},{"type":"text","marks":[{"type":"bold"}],"text":"cette"},{"type":"text","text":" option est ouverte, et l''option d''un invité déjà là ne peut basculer que vers celles ouvertes à "},{"type":"text","marks":[{"type":"bold"}],"text":"son"},{"type":"text","text":" invitante. Autrement dit : pas de pique-nique pour l''invité de quelqu''un qui n''y a pas droit — le serveur refuse aussi, pas seulement l''écran. En "},{"type":"text","marks":[{"type":"bold"}],"text":"niveau 2"},{"type":"text","text":", la liste reste en "},{"type":"text","marks":[{"type":"bold"}],"text":"lecture seule"},{"type":"text","text":"."}]}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Le bouton « Voir le détail »"},{"type":"text","text":" ouvre le "},{"type":"text","marks":[{"type":"bold"}],"text":"tableau"},{"type":"text","text":" (habitantes × jours/service). Chaque case indique l''un de "},{"type":"text","marks":[{"type":"bold"}],"text":"quatre"},{"type":"text","text":" états :"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Affichage"},{"type":"text","text":" : Libellé de l''option (vert) — "},{"type":"text","marks":[{"type":"bold"}],"text":"Signification"},{"type":"text","text":" : Elle mange cette option."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Affichage"},{"type":"text","text":" : "},{"type":"text","marks":[{"type":"bold"}],"text":"Non"},{"type":"text","text":" (rouge) — "},{"type":"text","marks":[{"type":"bold"}],"text":"Signification"},{"type":"text","text":" : Elle a "},{"type":"text","marks":[{"type":"bold"}],"text":"répondu"},{"type":"text","text":" qu''elle ne mange pas."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Affichage"},{"type":"text","text":" : "},{"type":"text","marks":[{"type":"bold"}],"text":"—"},{"type":"text","text":" (gris) — "},{"type":"text","marks":[{"type":"bold"}],"text":"Signification"},{"type":"text","text":" : Elle "},{"type":"text","marks":[{"type":"bold"}],"text":"n''a pas répondu"},{"type":"text","text":". Aucun repas compté, mais c''est une personne à "},{"type":"text","marks":[{"type":"bold"}],"text":"relancer"},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Affichage"},{"type":"text","text":" : 🌙 (lune orange) — "},{"type":"text","marks":[{"type":"bold"}],"text":"Signification"},{"type":"text","text":" : "},{"type":"text","marks":[{"type":"bold"}],"text":"Absente"},{"type":"text","text":" — déduit de son séjour d''absence."}]}]}]},{"type":"blockquote","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"« Non » et « — » ne sont pas la même chose."},{"type":"text","text":" Avant, l''appli ne faisait pas la différence : une résidente qui n''avait rien touché apparaissait comme un « Non ». Depuis le "},{"type":"text","marks":[{"type":"bold"}],"text":"03/08/2026"},{"type":"text","text":", « Non » est un "},{"type":"text","marks":[{"type":"bold"}],"text":"choix explicite"},{"type":"text","text":" de l''habitante, et « — » signale qu''elle "},{"type":"text","marks":[{"type":"bold"}],"text":"n''a rien renseigné"},{"type":"text","text":". Les repas "},{"type":"text","marks":[{"type":"bold"}],"text":"antérieurs"},{"type":"text","text":" à cette date continuent de s''afficher comme avant. L''"},{"type":"text","marks":[{"type":"bold"}],"text":"export CSV"},{"type":"text","text":" du détail reprend ces libellés (« Non », « Sans réponse », « Absente »)."}]}]},{"type":"paragraph","content":[{"type":"text","text":"Un invité apparaît en "},{"type":"text","marks":[{"type":"bold"}],"text":"petit badge « +👤 Prénom »"},{"type":"text","text":" dans la case de la personne qui l''a invité (jamais de ligne à part)."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"Onglet « Comptabilité »"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Récapitulatif de la période"},{"type":"text","text":" : total déjeuners / dîners "},{"type":"text","marks":[{"type":"bold"}],"text":"par résidence"},{"type":"text","text":", et un "},{"type":"text","marks":[{"type":"bold"}],"text":"grand total"},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Agrégat par personne"},{"type":"text","text":" : pour chaque personne, nombre de déjeuners et de dîners (les "},{"type":"text","marks":[{"type":"bold"}],"text":"« Non »"},{"type":"text","text":", les "},{"type":"text","marks":[{"type":"bold"}],"text":"sans réponse"},{"type":"text","text":" et les jours d''"},{"type":"text","marks":[{"type":"bold"}],"text":"absence"},{"type":"text","text":" ne comptent pas), "},{"type":"text","marks":[{"type":"bold"}],"text":"invités inclus"},{"type":"text","text":" pour la personne qui les a invités. "},{"type":"text","marks":[{"type":"bold"}],"text":"Tous les comptes activés"},{"type":"text","text":" apparaissent, même ceux inscrits à rien (0) — voir §3.1. La liste est triée "},{"type":"text","marks":[{"type":"bold"}],"text":"par nom puis prénom"},{"type":"text","text":" pour faciliter la facturation."}]}]}]},{"type":"blockquote","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Un départ en cours de période reste facturé."},{"type":"text","text":" Une personne "},{"type":"text","marks":[{"type":"bold"}],"text":"désactivée"},{"type":"text","text":" depuis n''est plus dans les listes courantes, mais elle "},{"type":"text","marks":[{"type":"bold"}],"text":"réapparaît"},{"type":"text","text":" dans la comptabilité de toute période où elle a réellement pris des repas : rien n''est perdu pour la facturation. Elle ne peut simplement plus être "},{"type":"text","marks":[{"type":"bold"}],"text":"ajoutée"},{"type":"text","text":" à une option."}]}]},{"type":"blockquote","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Déduction des absences"},{"type":"text","text":" : un séjour d''absence retire automatiquement les repas des "},{"type":"text","marks":[{"type":"bold"}],"text":"jours intérieurs"},{"type":"text","text":" ; le "},{"type":"text","marks":[{"type":"bold"}],"text":"premier"},{"type":"text","text":" et le "},{"type":"text","marks":[{"type":"bold"}],"text":"dernier"},{"type":"text","text":" jour restent au libre choix de la résidente (elle part après le dîner, revient avant le déjeuner)."}]}]},{"type":"horizontalRule"},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"8. Événements & calendrier"}]},{"type":"paragraph","content":[{"type":"text","text":"Cette section se lit à trois niveaux (voir §1) :"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Droit Événements"},{"type":"text","text":" : "},{"type":"text","marks":[{"type":"bold"}],"text":"Aucun"},{"type":"text","text":" — "},{"type":"text","marks":[{"type":"bold"}],"text":"Ce que la personne voit / fait"},{"type":"text","text":" : Elle voit les "},{"type":"text","marks":[{"type":"bold"}],"text":"événements"},{"type":"text","text":" et les "},{"type":"text","marks":[{"type":"bold"}],"text":"rappels"},{"type":"text","text":" qui la concernent, et "},{"type":"text","marks":[{"type":"bold"}],"text":"confirme sa participation"},{"type":"text","text":" — comme toute résidente."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Droit Événements"},{"type":"text","text":" : "},{"type":"text","marks":[{"type":"bold"}],"text":"Lecture"},{"type":"text","text":" — "},{"type":"text","marks":[{"type":"bold"}],"text":"Ce que la personne voit / fait"},{"type":"text","text":" : En plus : le bouton "},{"type":"text","marks":[{"type":"bold"}],"text":"« Voir les inscrits »"},{"type":"text","text":" sur les événements à confirmation ("},{"type":"text","marks":[{"type":"bold"}],"text":"qui"},{"type":"text","text":" a répondu présent — une personne "},{"type":"text","marks":[{"type":"bold"}],"text":"désactivée depuis"},{"type":"text","text":" son inscription y reste listée)."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Droit Événements"},{"type":"text","text":" : "},{"type":"text","marks":[{"type":"bold"}],"text":"Édition"},{"type":"text","text":" — "},{"type":"text","marks":[{"type":"bold"}],"text":"Ce que la personne voit / fait"},{"type":"text","text":" : En plus : "},{"type":"text","marks":[{"type":"bold"}],"text":"créer, modifier et supprimer"},{"type":"text","text":" des événements."}]}]}]},{"type":"blockquote","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"« Voir les inscrits » dépend de la section Événements"},{"type":"text","text":" (≥ Admin · consulter) et non du simple fait d''être admin. Une administratrice qui n''a de droits que sur "},{"type":"text","marks":[{"type":"bold"}],"text":"Repas"},{"type":"text","text":" n''y a donc pas accès : si elle en a besoin, passe-la à "},{"type":"text","marks":[{"type":"bold"}],"text":"Événements — Admin · consulter"},{"type":"text","text":"."}]},{"type":"paragraph","content":[{"type":"text","text":"Un "},{"type":"text","marks":[{"type":"bold"}],"text":"événement d''intendance"},{"type":"text","text":" ne se marque plus « réservé au staff » : cible-le sur un "},{"type":"text","marks":[{"type":"bold"}],"text":"groupe"},{"type":"text","text":" (ex. « Staff 12 »)."}]}]},{"type":"paragraph","content":[{"type":"text","text":"Avec le droit "},{"type":"text","marks":[{"type":"bold"}],"text":"Édition"},{"type":"text","text":", on renseigne pour un événement :"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"titre, dates (une ou plusieurs), horaires, lieu (résidence·s), couleur ;"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"visibilité"},{"type":"text","text":" : coche des "},{"type":"text","marks":[{"type":"bold"}],"text":"résidences / étages"},{"type":"text","text":" et/ou des "},{"type":"text","marks":[{"type":"bold"}],"text":"groupes"},{"type":"text","text":" (§3.2) ; la liste des "},{"type":"text","marks":[{"type":"bold"}],"text":"résidentes concernées"},{"type":"text","text":" — les "},{"type":"text","marks":[{"type":"bold"}],"text":"comptes activés"},{"type":"text","text":" (§3.1) — s''affiche dessous, pré-cochée, et l''on peut "},{"type":"text","marks":[{"type":"bold"}],"text":"décocher"},{"type":"text","text":" individuellement pour exclure quelqu''un. Voir §3.3. Le ciblage par résidence/étage est "},{"type":"text","marks":[{"type":"bold"}],"text":"dynamique"},{"type":"text","text":" (les futures arrivantes correspondant au filtre sont incluses automatiquement) ; un "},{"type":"text","marks":[{"type":"bold"}],"text":"groupe"},{"type":"text","text":", lui, se tient à jour à la main ;"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"rappel"},{"type":"text","text":" (nombre de jours avant) ;"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"demande de "},{"type":"text","marks":[{"type":"bold"}],"text":"confirmation de participation"},{"type":"text","text":"."}]}]}]},{"type":"horizontalRule"},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"9. Espace Administratif (infos pratiques)"}]},{"type":"paragraph","content":[{"type":"text","text":"L''onglet 📖 "},{"type":"text","marks":[{"type":"bold"}],"text":"Administratif"},{"type":"text","text":" (barre du bas) est "},{"type":"text","marks":[{"type":"bold"}],"text":"consultable par toutes"},{"type":"text","text":" mais "},{"type":"text","marks":[{"type":"bold"}],"text":"modifiable par les admins"},{"type":"text","text":" (bouton "},{"type":"text","marks":[{"type":"bold"}],"text":"« Modifier »"},{"type":"text","text":"). On y gère des "},{"type":"text","marks":[{"type":"bold"}],"text":"rubriques libres"},{"type":"text","text":" :"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Ajouter / renommer / réordonner / supprimer"},{"type":"text","text":" des rubriques ;"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"rubrique "},{"type":"text","marks":[{"type":"bold"}],"text":"texte"},{"type":"text","text":" (éditeur de mise en forme : gras, listes, titres, liens) ou rubrique "},{"type":"text","marks":[{"type":"bold"}],"text":"Contacts"},{"type":"text","text":" structurés (nom, rôle, téléphone, email cliquables) ;"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"une rubrique se "},{"type":"text","marks":[{"type":"bold"}],"text":"cible"},{"type":"text","text":" via "},{"type":"text","marks":[{"type":"bold"}],"text":"« Qui voit cette rubrique ? »"},{"type":"text","text":" (résidences, étages, groupes) : sans ciblage elle est visible par toutes ; ciblée sur un groupe « Intendance », elle reste interne (ex. le présent mode d''emploi). Le ciblage se règle "},{"type":"text","marks":[{"type":"bold"}],"text":"dès la création"},{"type":"text","text":" de la rubrique, en même temps que son titre et son type — pas besoin de la créer d''abord pour décider ensuite qui la voit."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Utilise-le pour le "},{"type":"text","marks":[{"type":"bold"}],"text":"règlement"},{"type":"text","text":", les "},{"type":"text","marks":[{"type":"bold"}],"text":"horaires"},{"type":"text","text":", les "},{"type":"text","marks":[{"type":"bold"}],"text":"contacts"},{"type":"text","text":", les "},{"type":"text","marks":[{"type":"bold"}],"text":"modes d''emploi"},{"type":"text","text":" et toute information générale du foyer."}]},{"type":"horizontalRule"},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"italic"}],"text":"Ce document accompagne le déploiement de l''application dans de nouveaux foyers. Le tenir à jour à chaque évolution fonctionnelle."}]}]}'
